using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Input;
using Microsoft.Win32;
namespace Configurator { public partial class MainWindow { private async void MenuDatabaseExportExcel_Click(object sender, RoutedEventArgs e) { var databaseName=_selectedDbName; if(string.IsNullOrWhiteSpace(databaseName)) databaseName=GetActiveDatabases().FirstOrDefault(); if(string.IsNullOrWhiteSpace(databaseName)){MessageBox.Show("Сначала подключите и выберите базу данных.","Экспорт БД",MessageBoxButton.OK,MessageBoxImage.Information);return;} var d=new SaveFileDialog{Title="Экспорт выбранной БД в Excel",Filter="Excel workbook (*.xlsx)|*.xlsx",DefaultExt=".xlsx",FileName=$"{databaseName}_SchemaExport.xlsx",AddExtension=true}; if(d.ShowDialog(this)!=true)return; try{Mouse.OverrideCursor=Cursors.Wait; await DatabaseExcelExportService.ExportAsync(_connection.ToConnectionString(databaseName),d.FileName); LogAction($"Экспорт БД «{databaseName}» в Excel: {Path.GetFileName(d.FileName)}"); MessageBox.Show($"Экспорт завершён.\n\nБаза: {databaseName}\nФайл: {d.FileName}","Экспорт БД",MessageBoxButton.OK,MessageBoxImage.Information);}catch(Exception ex){MessageBox.Show($"Не удалось экспортировать базу данных:\n\n{ex.Message}","Ошибка экспорта БД",MessageBoxButton.OK,MessageBoxImage.Error);}finally{Mouse.OverrideCursor=null;} } } }